class Solution {
public:
    vector<int> relocateMarbles(vector<int>& nums, vector<int>& moveFrom, vector<int>& moveTo) {
        set<int> pos(nums.begin(), nums.end());
        int m = moveFrom.size();
        for (int i = 0; i < m; ++i) {
            int u = moveFrom[i], v = moveTo[i];
            if (pos.count(u)) {
                pos.erase(u);
                pos.insert(v);
            }
        }
        return vector<int>(pos.begin(), pos.end());
    }
};

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

class Solution {
    public List<Integer> relocateMarbles(int[] nums, int[] moveFrom, int[] moveTo) {
        Set<Integer> pos = new HashSet<>();
        for (int x : nums) pos.add(x);
        for (int i = 0; i < moveFrom.length; i++) {
            int u = moveFrom[i], v = moveTo[i];
            if (pos.contains(u)) {
                pos.remove(u);
                pos.add(v);
            }
        }
        List<Integer> ans = new ArrayList<>(pos);
        Collections.sort(ans);
        return ans;
    }
}

var relocateMarbles = function(nums, moveFrom, moveTo) {
    const pos = new Set(nums);
    for (let i = 0; i < moveFrom.length; i++) {
        const u = moveFrom[i], v = moveTo[i];
        if (pos.has(u)) {
            pos.delete(u);
            pos.add(v);
        }
    }
    return Array.from(pos).sort((a, b) => a - b);
};
